const $ = document.querySelector.bind(document);
export default {
  methods: {
    isMultiScreen() {
      // for chrome
      if ('isExtended' in window.screen) {
        return window.screen.isExtended ? true : false;
      }

      // DOES NOT WORK IN FIREFOX no support is available
      return true;
    },

    async openWindowOnSelectedMonitor(monitorNumber, url) {
      if (this.isMultiScreen()) {
        // for chrome
        if ('getScreenDetails' in window) {
          const screenDetails = await window.getScreenDetails();
          const selectedScreen = screenDetails.screens[monitorNumber];
          this.external_window = window.open(
            url,
            '_blank',
            `left=${selectedScreen.availLeft},` +
              `top=${selectedScreen.availTop},` +
              `width=${selectedScreen.availWidth},` +
              `height=${selectedScreen.availHeight}`,
          );
        } else {
          // for other browsers
          const width = screen.width;
          const height = screen.height;
          let left = 0;
          let top = 0;

          if (monitorNumber == 1) {
            left = width; // Assuming the second monitor is to the right
          }

          this.external_window = window.open(
            url,
            '_blank',
            `left=${left},top=${top},width=${width},height=${height}`,
          );
        }
      }
    },

    async getMultiScreenDetails() {
      if (this.isMultiScreen()) {
        const screenDetails = await window.getScreenDetails();

        const primaryScreen = screenDetails.screens.find((s) => s.isPrimary);
        const otherScreen = screenDetails.screens.find(
          (s) => s !== primaryScreen,
        );
        window.open(
          'https://www.google.com/',
          '_blank',
          `left=${otherScreen.availLeft},` +
            `top=${otherScreen.availTop},` +
            `width=${otherScreen.availWidth},` +
            `height=${otherScreen.availHeight}`,
        );
      }
    },
  },
};
