<!--vbase-->
<template>
  <!-- Any table, not just AI: both table views honour remove_unmapped_columns. -->
  <template v-if="hasTable()">
    <q-btn
      flat
      dense
      v-if="remove_unmapped_columns"
      id="non_mapped_columns"
      class="icon-grey validation-footer-table-button"
      @click="handleClick()"
    >
      <Icon icon="mdi:table-eye" width="20" height="20" />
      <q-tooltip>{{ $t('show_non_mapped_columns') }}</q-tooltip>
    </q-btn>
    <q-btn
      flat
      dense
      v-else
      id="non_mapped_columns"
      class="icon-grey validation-footer-table-button"
      @click="handleClick()"
    >
      <Icon icon="mdi:table-eye-off" width="20" height="20" />
      <q-tooltip>{{ $t('hide_non_mapped_columns') }}</q-tooltip>
    </q-btn>
  </template>
</template>

<script lang="ts">

import { defineComponent } from 'vue';
import { useDocumentStore } from 'src/store/main';
import helperMixin from 'src/mixins/helperMixin';
import { storeToRefs } from 'pinia';

export default defineComponent({
  el: '#app',
  mixins: [helperMixin],
  
  props: {
    isReadOnly: {
      type: Boolean,
      default: false,
    },
  },
  data() {
    return {};
  },
  methods: {
    handleClick() {
      if (this.isReadOnly) {
        return;
      }

      if (!this.setUnmappedColumnsHidden(!this.remove_unmapped_columns)) {
        return;
      }
      const event = new CustomEvent('render_map_coulums', {});
      document.dispatchEvent(event);
    },
  },
  setup() {
    const doc_store = useDocumentStore();
    const { record, remove_unmapped_columns } = storeToRefs(doc_store);
    const { setUnmappedColumnsHidden, hasTable } = doc_store;

    return {
      remove_unmapped_columns,
      record,
      setUnmappedColumnsHidden,
      hasTable,
    };
  },
});
</script>

<style lang="scss" scoped></style>
