<!--vbase-->
<template>
  <q-btn
    flat
    dense
    id="block_supplier_table_extraction"
    class="icon-grey validation-footer-table-button"
    @click="
      (e: any) => {
        e.stopPropagation();
        openSupplierBlockDialog();
      }
    "
  >
    <Icon icon="mdi:account-cancel" width="20" height="20" />
    <q-tooltip>{{ $t('block_supplier_tooltip') }}</q-tooltip>
  </q-btn>
  <q-dialog
    v-model="confirm_supplier_block"
    @keydown.esc="confirm_supplier_block = false"
    @hide="confirm_supplier_block = false"
  >
    <q-card>
      <q-card-section class="row items-center">
        <q-avatar icon="block" color="primary" text-color="white" />
        <span class="q-ml-sm">{{ $t('block_supplier_confirmation') }}</span>
      </q-card-section>

      <q-card-actions align="right">
        <f-btn appearance="cancel" :label="$t('cancel')" v-close-popup />

        <f-btn
          class="q-mr-sm"
          data-cy="setvatfield"
          :label="$t('confirm')"
          @click="blockSupplierTableExtraction"
        />
      </q-card-actions>
    </q-card>
  </q-dialog>
</template>

<script lang="ts">

import { defineComponent, ref } from 'vue';
import { useDocumentStore } from 'src/store/main';
import helperMixin from 'src/mixins/helperMixin';
import { documentSupplierApiService } from 'src/services';
import { storeToRefs } from 'pinia';
import type { dynamicObj } from 'src/pages/assets';
import { ApiExceptions } from 'src/exceptions/index';
import { notify } from 'src/components/notifications/notify';

export default defineComponent({
  el: '#app',
  mixins: [helperMixin],
  
  props: {
    isReadOnly: {
      type: Boolean,
      default: false,
    },
  },
  data() {
    return {};
  },
  methods: {
    openSupplierBlockDialog() {
      if (this.isReadOnly) {
        return;
      }
      this.confirm_supplier_block = true;
    },
    async blockSupplierTableExtraction() {
      try {
        if (this.isReadOnly) {
          return;
        }
        if (!this.supplier) {
          notify.error(this.$t('SUPPLIER_NAME_MISSING'));
          return;
        }

        const data = {} as dynamicObj;
        data.doc_type = this.record.doc_type;
        data.is_org_specific = true;
        data.tfidf_id = this.supplier;

        if (this.record.filter_values && this.record.filter_values.length > 0) {
          this.record.filter_values.forEach(function (
            value: string,
            i: number,
          ) {
            let field_name = 'filterID' + (i + 1);
            data[field_name] = value;
          });
        }

        this.showLoading();
        const response =
          await documentSupplierApiService.blockSupplierForTableExtraction(
            data,
          );
        if (!response || response.success === false) {
          throw { message: response.message };
        }

        await this.updateDocument();
        this.confirm_supplier_block = false;
        this.$router.go(0);
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },

    async updateDocument() {
      this.record.tables = [];
      this.record.table_blocked = true;
      await this.saveDocument(this.record.doc_id);
      await this.setDataToCache();
    },
  },
  setup() {
    const doc_store = useDocumentStore();
    const { doc_loaded, record, supplier } = storeToRefs(doc_store);
    const { saveDocument, setDataToCache } = doc_store;
    return {
      setDataToCache,
      supplier,
      saveDocument,
      doc_loaded,
      record,
      confirm_supplier_block: ref(false),
    };
  },
});
</script>

<style lang="scss" scoped>
.block-icon {
  padding: 0px !important;
  padding-bottom: 4px !important;
}
</style>
