<!--vbase-->
<template>
  <div class="row text-center q-pt-xs q-pb-xs slider-bg">
    <div class="scale" :style="'left:' + gaugeValue + '%'"></div>
    <div class="col-xs-3 col-sm-3 col-md-3 col-lg-3">UNRELIABLE</div>
    <div class="col-xs-3 col-sm-3 col-md-3 col-lg-3">AVERAGE</div>
    <div class="col-xs-3 col-sm-3 col-md-3 col-lg-3">RELIABLE</div>
    <div class="col-xs-3 col-sm-3 col-md-3 col-lg-3">PERFECT</div>
  </div>
</template>

<script lang="ts">
import { defineComponent, ref } from 'vue';

export default defineComponent({
  el: '#ai_severity_level',
  data() {
    return {
      gaugeValue: ref(5),
    };
  },
  mounted: function () {
    document.addEventListener('TE_gauge_calculation', this.TEGaugeCalculation);
    document.addEventListener('FV_gauge_calculation', this.FVGaugeCalculation);
  },
  unmounted: function () {
    document.removeEventListener(
      'TE_gauge_calculation',
      this.TEGaugeCalculation,
    );
    document.removeEventListener(
      'FV_gauge_calculation',
      this.FVGaugeCalculation,
    );
  },

  methods: {
    TEGaugeCalculation(e: any) {
      if (
        !e ||
        !e.detail ||
        !e.detail.hasOwnProperty('min_table_effective_weight')
      ) {
        return;
      }
      this.calculateGaugeValue(e.detail.min_table_effective_weight);
    },
    FVGaugeCalculation(e: any) {
      if (
        !e ||
        !e.detail ||
        !e.detail.hasOwnProperty('mean_effective_weight')
      ) {
        return;
      }
      this.calculateGaugeValue(e.detail.mean_effective_weight);
    },
    calculateGaugeValue(effectiveWeight: number) {
      this.gaugeValue = Math.round(effectiveWeight * 10);

      if (this.gaugeValue < 5) {
        this.gaugeValue = 5;
      }
    },
  },
  setup() {
    return {};
  },
});
</script>

