<!--vbase-->
<template>
  <q-icon
    size="30px"
    v-if="record.table_blocked"
    @click="openSupplierBlockDialog()"
    class="q-mr-sm cursor-pointer"
  >
    <Icon icon="mdi:account-check" width="30" height="30" />
    <q-tooltip>{{ $t('unblock_supplier') }}</q-tooltip>
  </q-icon>

  <q-dialog
    v-model="confirm_supplier_unblock"
    @keydown.esc="confirm_supplier_unblock = false"
    @hide="confirm_supplier_unblock = false"
  >
    <q-card>
      <q-card-section class="row items-center">
        <q-avatar icon="block" color="primary" />
        <span class="q-ml-sm">{{ $t('unblock_supplier_confirmation') }}</span>
      </q-card-section>

      <q-card-actions align="right">
        <f-btn appearance="cancel" :label="$t('cancel')" v-close-popup />

        <f-btn
          class="q-mr-sm"
          :label="$t('confirm')"
          @click="unBlockedSupplier"
        />
      </q-card-actions>
    </q-card>
  </q-dialog>
</template>

<script lang="ts">
import { defineComponent, ref } from 'vue';

import { useDocumentStore } from 'src/store/main';
import helperMixin from 'src/mixins/helperMixin';
import { storeToRefs } from 'pinia';
import type { dynamicObj } from 'src/pages/assets';
import { ApiExceptions } from 'src/exceptions/index';
import { notify } from 'src/components/notifications/notify';
import {
  documentSupplierApiService,
  documentDetailApiService,
} from 'src/services';

export default defineComponent({
  el: '#app',
  mixins: [helperMixin],
  props: {
    isReadOnly: {
      type: Boolean,
      default: false,
    },
  },
  
  data() {
    return {};
  },
  methods: {
    openSupplierBlockDialog() {
      if (this.isReadOnly) {
        return;
      }
      this.confirm_supplier_unblock = true;
    },
    async unBlockedSupplier() {
      try {
        if (!this.supplier) {
          throw 'No Supplier found to unblock';
        }

        this.showLoading();
        const delete_response =
          await documentSupplierApiService.deleteSupplierBySupplier(
            this.supplier,
          );
        if (delete_response.success === false) {
          throw { message: delete_response.message };
        }

        const response = await documentDetailApiService.restartDocument(
          this.record.doc_id,
        );
        if (response.success === false) {
          throw { message: 'Failed to unblock' };
        }

        this.$router.push('/dashboard');
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
        this.confirm_supplier_unblock = false;
      }
    },
  },
  setup() {
    const doc_store = useDocumentStore();
    const { record, supplier } = storeToRefs(doc_store);
    return {
      supplier,
      record,
      confirm_supplier_unblock: ref(false),
    };
  },
});
</script>

<style lang="scss" scoped>
.block-icon {
  padding: 0px !important;
  padding-bottom: 4px !important;
}
</style>
